/* Public API: bridge entrypoints for embedding in a shim device. */
uint64_t entropy_src_read(void *opaque, hwaddr addr, unsigned size);
void     entropy_src_write(void *opaque, hwaddr addr,
                   uint64_t value, unsigned size);
/* Asserts rst_ni for one settle round, then releases — primes the
 * model so registers with non-zero RESVALs see their reset value. */
void entropy_src_reset(entropy_src_state *s);
/* Run the model to quiescence without a bus access (external event
 * sources — SPI pumps, pin changes — call this after poking inputs). */
void entropy_src_settle(entropy_src_state *s);

void entropy_src_step(entropy_src_state *s);
void entropy_src_update(entropy_src_state *s);
void entropy_src_tick(entropy_src_state *s);

void entropy_src_step_many(entropy_src_state *s, unsigned count);

/* Phase 2.d input setters — bridge host-side QEMU events into
 * the simulated device.  Each writes one input-port leaf field
 * and runs update_state→tick→update_state to settle.
 */
